"""Read the stakeholder contracts and decide where each rule runs.

Shared by compile.py (writes the dbt tests and GX suites), validate.py (runs the
GX suites) and reconcile.py (joins both engines' results at the end of the day).

Routing, cheapest place first:
  1. A rule on a file that is not loaded yet goes to Great Expectations: dbt can
     only test what is already in the warehouse.
  2. A rule with a tolerance or a distribution (mostly, mean, sum, row count)
     goes to Great Expectations, which has these built in and reports the
     observed value. In dbt each would be a hand-written macro.
  3. Any other rule on a model is set-based SQL, so it becomes a dbt test that
     runs in the warehouse inside `dbt build`. If the project already has the
     same generic test, the contract reuses it instead of running it twice.
"""

from __future__ import annotations

import json
import re
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parents[1]
CONTRACTS = ROOT / "contracts"
DBT_TESTS = ROOT / "tests" / "contracts"
GX_SUITES = CONTRACTS / "gx" / "expectations"
MANIFEST = ROOT / "target" / "manifest.json"
PROJECT = "nexus_partner_analytics"

DBT_CHECKS = {"unique", "not_null", "accepted_values", "between", "regex", "expression", "reconciles"}
GX_CHECKS = {
    "columns_match", "regex", "accepted_values", "row_count", "between",
    "unique_combination", "sum", "mean", "unique", "not_null",
}
TOLERANCE_CHECKS = {"row_count", "sum", "mean"}
REUSABLE = {"unique", "not_null", "accepted_values"}

ENGINES = {
    "gx": "Great Expectations",
    "dbt": "dbt test (generated)",
    "dbt_existing": "dbt test (already in the project)",
}
REASONS = {
    "boundary": "The file is not in the warehouse yet, so dbt cannot see it. GX checks the file as delivered and stops a bad drop before it loads.",
    "tolerance": "A tolerance or distribution check. GX has it built in and reports the observed value; in dbt it would be a custom macro.",
    "gx_only": "No set-based SQL form of this check, so it runs in GX.",
    "set_based": "Set-based SQL on a model. It runs in the warehouse inside dbt build, moves no rows, and a failure stops downstream models.",
    "reuse": "The project already runs this exact dbt test, so the contract links to it rather than testing twice.",
}


def contract_files() -> list[Path]:
    return sorted(CONTRACTS.glob("*.yml"))


def dbt_vars() -> dict:
    return yaml.safe_load((ROOT / "dbt_project.yml").read_text()).get("vars", {})


def render_vars(text: str) -> str:
    """Replace {{ var('x') }} with its dbt_project.yml value, for SQL run outside dbt."""
    values = dbt_vars()
    return re.sub(r"\{\{\s*var\(['\"](\w+)['\"]\)\s*\}\}", lambda m: str(values[m.group(1)]), text)


def existing_tests() -> dict[tuple, dict]:
    """Generic tests already in the project, keyed by (check, model, column, values)."""
    if not MANIFEST.exists():
        raise SystemExit("target/manifest.json is missing; run `dbt parse --profiles-dir .` first")
    found = {}
    for node in json.loads(MANIFEST.read_text())["nodes"].values():
        meta = node.get("test_metadata")
        if node["resource_type"] != "test" or not meta or not node.get("attached_node"):
            continue
        if node["original_file_path"].startswith("tests/contracts/"):
            continue
        values = meta.get("kwargs", {}).get("values")
        key = (meta["name"], node["attached_node"].split(".")[-1], node.get("column_name"),
               tuple(map(str, values)) if values else None)
        found[key] = {"name": node["name"], "unique_id": node["unique_id"], "path": node["original_file_path"]}
    return found


def route(rule: dict, dataset: dict, existing: dict) -> tuple[str, str, dict | None]:
    check = rule["check"]
    if dataset["kind"] == "file":
        engine, reason = "gx", "boundary"
    elif rule.get("mostly") is not None or check in TOLERANCE_CHECKS:
        engine, reason = "gx", "tolerance"
    elif check not in DBT_CHECKS:
        engine, reason = "gx", "gx_only"
    else:
        engine, reason = "dbt", "set_based"
    if engine == "gx" and check not in GX_CHECKS:
        raise SystemExit(f"{rule['id']}: Great Expectations has no mapping for check '{check}'")
    reused = None
    if engine == "dbt" and check in REUSABLE and rule.get("severity", "error") == "error":
        values = tuple(map(str, rule["values"])) if rule.get("values") else None
        reused = existing.get((check, rule["dataset"], rule.get("column"), values))
        if reused:
            engine, reason = "dbt_existing", "reuse"
    return engine, reason, reused


def load() -> list[dict]:
    """Every contract, with each rule's engine, reason and artifact name."""
    existing = existing_tests()
    contracts = []
    for path in contract_files():
        spec = yaml.safe_load(path.read_text())
        datasets = {d["name"]: d for d in spec["datasets"]}
        rules = []
        for rule in spec["rules"]:
            dataset = datasets[rule["dataset"]]
            engine, reason, reused = route(rule, dataset, existing)
            slug = rule["id"].lower().replace("-", "")
            rules.append({
                **rule,
                "severity": rule.get("severity", "error"),
                "dataset_kind": dataset["kind"],
                "engine": engine,
                "reason": reason,
                "test_name": reused["name"] if reused else f"contract_{spec['contract']}_{slug}" if engine == "dbt" else None,
                "reused": reused,
                "suite": f"{spec['contract']}__{rule['dataset']}" if engine == "gx" else None,
            })
        contracts.append({**spec, "path": path.relative_to(ROOT).as_posix(), "source": path.read_text(),
                          "datasets": datasets, "rules": rules})
    return contracts


# ---- dbt: one singular test per rule ------------------------------------------

def _literal(value) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return str(value)
    return "'" + str(value).replace("'", "''") + "'"


def dbt_body(rule: dict, ref) -> str:
    """The failing-rows query for a dbt-routed rule. `ref` renders a model reference."""
    check, model, col = rule["check"], ref(rule["dataset"]), rule.get("column")
    if check == "unique":
        return f"select {col}, count(*) as occurrences\nfrom {model}\ngroup by {col}\nhaving count(*) > 1"
    if check == "not_null":
        return f"select *\nfrom {model}\nwhere {col} is null"
    if check == "accepted_values":
        values = ", ".join(_literal(v) for v in rule["values"])
        return f"select *\nfrom {model}\nwhere {col} not in ({values})"
    if check == "between":
        bounds = [f"{col} < {rule['min']}" if "min" in rule else None, f"{col} > {rule['max']}" if "max" in rule else None]
        return f"select *\nfrom {model}\nwhere " + " or ".join(b for b in bounds if b)
    if check == "regex":
        return f"select *\nfrom {model}\nwhere not regexp_matches({col}, {_literal(rule['pattern'])})"
    if check == "expression":
        return f"select *\nfrom {model}\nwhere not ({rule['expression']})"
    if check == "reconciles":
        right = rule["right"]
        reference = (f"select {right['value']} as value" if "value" in right
                     else f"select {right['expression']} as value from {ref(right['model'])}")
        tolerance = rule.get("tolerance", 0)
        return (
            f"with contract_side as (\n    select {rule['left']} as value from {model}\n),\n"
            f"reference_side as (\n    {reference}\n)\n"
            "select c.value as contract_value, r.value as reference_value\n"
            "from contract_side c cross join reference_side r\n"
            f"where c.value is null or r.value is null or abs(c.value - r.value) > {tolerance}"
        )
    raise SystemExit(f"{rule['id']}: no dbt template for check '{check}'")


def dbt_test(contract: dict, rule: dict) -> str:
    """The generated dbt singular test file for a rule."""
    config = (
        f"{{{{ config(tags=['contract', 'contract_{contract['contract']}'], severity='{rule['severity']}',\n"
        f"          meta={{'contract': '{contract['contract']}', 'rule': '{rule['id']}'}}) }}}}"
    )
    header = (
        f"-- Generated by contracts/compile.py from {contract['path']} (rule {rule['id']}). Do not edit.\n"
        f"-- {rule['description']}\n"
    )
    return header + config + "\n\n" + dbt_body(rule, lambda m: f"{{{{ ref('{m}') }}}}") + "\n"


def plain_sql(rule: dict) -> str:
    """The same failing-rows query with plain table names, to run in the browser."""
    return render_vars(dbt_body(rule, lambda m: m))


# ---- Great Expectations: one suite per contract and dataset --------------------

def expectation(rule: dict):
    import great_expectations.expectations as gxe

    check, col = rule["check"], rule.get("column")
    extra = {"meta": {"rule": rule["id"]}, "severity": "warning" if rule["severity"] == "warn" else "critical"}
    if rule.get("mostly") is not None:
        extra["mostly"] = rule["mostly"]
    bounds = {"min_value": rule.get("min"), "max_value": rule.get("max")}
    if check == "columns_match":
        return gxe.ExpectTableColumnsToMatchOrderedList(column_list=rule["columns"], **extra)
    if check == "regex":
        return gxe.ExpectColumnValuesToMatchRegex(column=col, regex=rule["pattern"], **extra)
    if check == "accepted_values":
        return gxe.ExpectColumnValuesToBeInSet(column=col, value_set=rule["values"], **extra)
    if check == "row_count":
        return gxe.ExpectTableRowCountToBeBetween(**bounds, **extra)
    if check == "between":
        return gxe.ExpectColumnValuesToBeBetween(column=col, **bounds, **extra)
    if check == "unique_combination":
        return gxe.ExpectCompoundColumnsToBeUnique(column_list=rule["columns"], **extra)
    if check == "sum":
        return gxe.ExpectColumnSumToBeBetween(column=col, **bounds, **extra)
    if check == "mean":
        return gxe.ExpectColumnMeanToBeBetween(column=col, **bounds, **extra)
    if check == "unique":
        return gxe.ExpectColumnValuesToBeUnique(column=col, **extra)
    if check == "not_null":
        return gxe.ExpectColumnValuesToNotBeNull(column=col, **extra)
    raise SystemExit(f"{rule['id']}: no Great Expectations mapping for check '{check}'")


def gx_suites(contract: dict) -> dict[str, dict]:
    """Suite name -> serialised GX expectation suite, for this contract's GX rules."""
    import great_expectations as gx

    suites = {}
    for dataset in contract["datasets"].values():
        rules = [r for r in contract["rules"] if r["engine"] == "gx" and r["dataset"] == dataset["name"]]
        if not rules:
            continue
        name = f"{contract['contract']}__{dataset['name']}"
        suite = gx.ExpectationSuite(
            name=name,
            expectations=[expectation(r) for r in rules],
            meta={"contract": contract["contract"], "contract_version": contract["version"],
                  "dataset": dataset["name"], "dataset_kind": dataset["kind"],
                  **({"path": dataset["path"]} if dataset["kind"] == "file" else {}),
                  "generated_from": contract["path"]},
        )
        suites[name] = suite.to_json_dict()
    return suites

"""Compile the stakeholder contracts into dbt tests and Great Expectations suites.

    python contracts/compile.py          # write tests/contracts/*.sql and contracts/gx/expectations/*.json
    python contracts/compile.py --check  # fail if the committed files differ from the contracts

Needs target/manifest.json (from `dbt parse`) to find dbt tests the project already has.
"""

from __future__ import annotations

import argparse
import json
import sys

from contract_plan import DBT_TESTS, GX_SUITES, ROOT, dbt_test, gx_suites, load


def render() -> dict:
    files = {}
    for contract in load():
        for rule in contract["rules"]:
            if rule["engine"] == "dbt":
                files[DBT_TESTS / f"{rule['test_name']}.sql"] = dbt_test(contract, rule)
        for name, suite in gx_suites(contract).items():
            files[GX_SUITES / f"{name}.json"] = json.dumps(suite, indent=2) + "\n"
    return files


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    files = render()
    current = set(DBT_TESTS.glob("*.sql")) | set(GX_SUITES.glob("*.json"))
    stale = sorted(
        [p for p, text in files.items() if not p.exists() or p.read_text() != text] + list(current - set(files))
    )
    if args.check:
        if stale:
            sys.exit("Contract tests are stale; run contracts/compile.py: "
                     + ", ".join(p.relative_to(ROOT).as_posix() for p in stale))
        print(f"{len(files)} generated contract files match the contracts")
        return
    for path in current - set(files):
        path.unlink()
    for path, text in files.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text)
    dbt = sum(p.suffix == ".sql" for p in files)
    print(f"Wrote {dbt} dbt tests and {len(files) - dbt} GX suites")


if __name__ == "__main__":
    main()

"""End-of-day reconciliation: one verdict per stakeholder contract.

    python contracts/reconcile.py          # write assets/contracts.json
    python contracts/reconcile.py --check  # fail if it is stale, or a contract is held

Joins the two engines' results rule by rule (dbt from target/run_results.json,
Great Expectations from target/gx_results/), then checks each reconcile
chain in the contracts: the same number, measured from the delivered file
through to the mart a stakeholder reads, must agree within tolerance.
"""

from __future__ import annotations

import argparse
import json
import sys

import duckdb

from contract_plan import ENGINES, REASONS, ROOT, dbt_test, dbt_vars, load, plain_sql, render_vars

DATABASE = ROOT / "target" / "nexus_partner_analytics.duckdb"
RUN_RESULTS = ROOT / "target" / "run_results.json"
GX_RESULTS = ROOT / "target" / "gx_results"
OUTPUT = ROOT / "assets" / "contracts.json"
SOURCES = [
    "contracts/README.md", "contracts/contract_plan.py", "contracts/compile.py",
    "contracts/validate.py", "contracts/reconcile.py",
]


def _dbt_results() -> dict:
    if not RUN_RESULTS.exists():
        sys.exit("target/run_results.json is missing; run `dbt build --profiles-dir .` first")
    return {r["unique_id"]: r for r in json.loads(RUN_RESULTS.read_text())["results"]}


def _gx_results() -> dict:
    files = sorted(GX_RESULTS.glob("*.json"))
    if not files:
        sys.exit("target/gx_results/ is empty; run contracts/validate.py first")
    return {r["rule"]: r for f in files for r in json.loads(f.read_text())["results"]}


def _num(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return value
    value = round(float(value), 4)
    return int(value) if value.is_integer() else value


def _gx_outcome(rule: dict, gx: dict) -> dict:
    found = gx.get(rule["id"])
    if not found:
        sys.exit(f"{rule['id']}: no Great Expectations result; rerun contracts/validate.py")
    res = found["result"]
    status = "pass" if found["success"] else ("warn" if rule["severity"] == "warn" else "fail")
    if "unexpected_count" in res:
        n, bad = res["element_count"], res["unexpected_count"]
        observed = f"{bad} of {n} rows outside ({round(res['unexpected_percent'], 1)}%)"
        if rule.get("mostly") is not None:
            observed += f"; needs at least {int(rule['mostly'] * 100)}% inside"
    elif isinstance(res.get("observed_value"), list):
        observed = f"{len(res['observed_value'])} columns, in the agreed order" if found["success"] else "column layout differs"
    else:
        observed = f"observed {_num(res.get('observed_value'))}"
    return {"status": status, "observed": observed, "value": _num(res.get("observed_value")) if not isinstance(res.get("observed_value"), list) else None,
            "expectation": found["expectation"]}


def _dbt_outcome(rule: dict, dbt: dict) -> dict:
    unique_id = rule["reused"]["unique_id"] if rule["reused"] else f"test.nexus_partner_analytics.{rule['test_name']}"
    found = dbt.get(unique_id)
    if not found:
        sys.exit(f"{rule['id']}: {rule['test_name']} did not run; run `dbt build --profiles-dir .` first")
    status = {"pass": "pass", "warn": "warn", "fail": "fail"}.get(found["status"], "fail")
    failures = found.get("failures") or 0
    return {"status": status, "observed": f"{failures} failing row{'s' if failures != 1 else ''}", "value": failures}


def _artifact(contract: dict, rule: dict, suites: dict) -> dict:
    if rule["engine"] == "dbt":
        return {"path": f"tests/contracts/{rule['test_name']}.sql", "language": "sql", "code": dbt_test(contract, rule)}
    if rule["engine"] == "dbt_existing":
        reused = rule["reused"]
        return {"path": reused["path"], "language": "text",
                "code": f"# Already declared in {reused['path']}; dbt names it\n{reused['name']}\n"}
    suite = suites[rule["suite"]]
    exp = next(e for e in suite["expectations"] if e["meta"]["rule"] == rule["id"])
    return {"path": f"contracts/gx/expectations/{rule['suite']}.json", "language": "json",
            "code": json.dumps(exp, indent=2) + "\n"}


def _reconcile(spec: dict, rules: dict, con) -> dict:
    measures = []
    for m in spec["measures"]:
        if "rule" in m:
            value, source = rules[m["rule"]]["value"], f"Great Expectations observed value of {m['rule']}"
        else:
            sql = render_vars(m["sql"])
            value, source = _num(con.execute(sql).fetchone()[0]), sql
        measures.append({"label": m["label"], "value": value, "source": source, "engine": "gx" if "rule" in m else "sql"})
    values = [m["value"] for m in measures]
    spread = round(max(values) - min(values), 4) if all(v is not None for v in values) else None
    tolerance = spec.get("tolerance", 0)
    status = "match" if spread is not None and spread <= tolerance else "mismatch"
    return {"id": spec["id"], "title": spec["title"], "tolerance": tolerance, "spread": spread,
            "status": status, "measures": measures}


def render() -> tuple[str, list[str]]:
    dbt, gx = _dbt_results(), _gx_results()
    from contract_plan import gx_suites  # imports great_expectations only when needed

    con = duckdb.connect(str(DATABASE), read_only=True)
    contracts, held = [], []
    for contract in load():
        suites = gx_suites(contract)
        rules = []
        for rule in contract["rules"]:
            outcome = _gx_outcome(rule, gx) if rule["engine"] == "gx" else _dbt_outcome(rule, dbt)
            rules.append({
                "id": rule["id"], "description": rule["description"], "dataset": rule["dataset"],
                "dataset_kind": rule["dataset_kind"], "check": rule["check"],
                "column": rule.get("column") or ", ".join(rule.get("columns", [])) or None,
                "severity": rule["severity"], "engine": rule["engine"], "reason": rule["reason"],
                "artifact": _artifact(contract, rule, suites),
                "sql": plain_sql(rule) if rule["engine"] != "gx" else None,
                **outcome,
            })
        by_id = {r["id"]: r for r in rules}
        recs = [_reconcile(spec, by_id, con) for spec in contract.get("reconcile", [])]
        failed = [r["id"] for r in rules if r["status"] == "fail"] + [r["id"] for r in recs if r["status"] == "mismatch"]
        warned = [r["id"] for r in rules if r["status"] == "warn"]
        verdict = "held" if failed else "signed_off_with_warnings" if warned else "signed_off"
        if failed:
            held.append(f"{contract['contract']}: {', '.join(failed)}")
        contracts.append({
            "contract": contract["contract"], "title": contract["title"], "version": contract["version"],
            "stakeholder": contract["stakeholder"], "consumer": contract["consumer"],
            "owner_group": contract["owner_group"], "sla": contract["sla"], "path": contract["path"],
            "source": contract["source"], "verdict": verdict, "failed": failed, "warned": warned,
            "datasets": list(contract["datasets"].values()), "rules": rules, "reconcile": recs,
        })

    all_rules = [r for c in contracts for r in c["rules"]]
    all_recs = [r for c in contracts for r in c["reconcile"]]
    generated = sorted({r["artifact"]["path"] for r in all_rules if r["engine"] != "dbt_existing"})
    files = [{"path": p, "language": "markdown" if p.endswith(".md") else "python", "code": (ROOT / p).read_text()} for p in SOURCES]
    files += [{"path": p, "language": "sql" if p.endswith(".sql") else "json", "code": (ROOT / p).read_text()} for p in generated]
    data = {
        "business_date": dbt_vars()["cost_as_of_date"],
        "engines": ENGINES,
        "reasons": REASONS,
        "summary": {
            "contracts": len(contracts),
            "rules": len(all_rules),
            "engines": {e: sum(r["engine"] == e for r in all_rules) for e in ENGINES},
            "status": {s: sum(r["status"] == s for r in all_rules) for s in ("pass", "warn", "fail")},
            "reconciliations": len(all_recs),
            "reconciled": sum(r["status"] == "match" for r in all_recs),
        },
        "contracts": contracts,
        "files": files,
    }
    return json.dumps(data, indent=2) + "\n", held


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    rendered, held = render()
    if args.check:
        if not OUTPUT.exists() or OUTPUT.read_text() != rendered:
            sys.exit("assets/contracts.json is stale; run contracts/reconcile.py")
        print("Contract results match the build")
    else:
        OUTPUT.write_text(rendered)
        print(f"Wrote {OUTPUT.relative_to(ROOT)}")
    if held:
        sys.exit("Contracts held at end of day: " + "; ".join(held))


if __name__ == "__main__":
    main()

